package com.mst.controllers.sale;import com.mst.models.dto.SaleOutwardGatePassRequest;import com.mst.services.SaleOutwardGatePassService;import java.time.LocalDate;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/sale/outward-gate-pass/api") public class SaleOutwardGatePassController{private final SaleOutwardGatePassService s;public SaleOutwardGatePassController(SaleOutwardGatePassService s){this.s=s;}@GetMapping("/initial")Object initial(){return s.initial();}@GetMapping("/type-code")Object code(@RequestParam String type){return s.typeCode(type);}@GetMapping("/reference")Object ref(@RequestParam int type,@RequestParam int code,@RequestParam LocalDate date){return s.reference(type,code,date);}@GetMapping("/history")Object history(){return s.history();}@GetMapping("/{id}")Object record(@PathVariable int id){return s.record(id);}@PostMapping Object save(@RequestBody SaleOutwardGatePassRequest r){return s.save(r);}}
